```python
class Renderer(Protocol):
    def render_circle(self, radius: float) -> None: ...

class VectorRenderer:
    def render_circle(self, radius: float) -> None:
        print(f"Drawing vector circle, r={radius}")

class RasterRenderer:
    def render_circle(self, radius: float) -> None:
        print(f"Drawing raster circle, r={radius}")

class Circle:
    def __init__(self, radius: float, renderer: Renderer):
        self._radius = radius
        self._renderer = renderer

    def draw(self) -> None:
        self._renderer.render_circle(self._radius)
```

`Circle(5, VectorRenderer())` and `Circle(5, RasterRenderer())` are the same shape, drawn two different ways — no `VectorCircle` or `RasterCircle` subclass exists, or ever needs to.

```python
class Glyph:  # intrinsic state only — shared, immutable
    def __init__(self, char: str, font: str, size: int):
        self.char, self.font, self.size = char, font, size

class GlyphFactory:
    _pool: dict[tuple, Glyph] = {}

    @classmethod
    def get(cls, char: str, font: str, size: int) -> Glyph:
        key = (char, font, size)
        if key not in cls._pool:
            cls._pool[key] = Glyph(char, font, size)
        return cls._pool[key]

document = [(GlyphFactory.get("a", "Arial", 12), x, y) for x, y in positions]  # x, y are extrinsic
```

A million-character document reuses maybe a few hundred `Glyph` instances — one per distinct char/font/size combination — instead of allocating a million nearly-identical objects.
